// ─── File: DistributedMonolithDemo.java ───
// Contrasts a distributed monolith (sync chain, shared DB) with a decoupled design.
import java.util.*;
import java.util.logging.*;

public class DistributedMonolithDemo {
    private static final Logger log = Logger.getLogger("DM");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DownstreamService account = new DownstreamService("account", false);
        DownstreamService fraud = new DownstreamService("fraud", false);
        DownstreamService creditSlow = new DownstreamService("credit", true); // slow/failing

        // BAD: synchronous chain loan→account→fraud→credit; credit fails → whole chain fails.
        log.info("=== distributed monolith: synchronous chain cascades ===");
        CoupledLoanService coupled = new CoupledLoanService(account, fraud, creditSlow);
        coupled.approve("LN-1", "SAV2001");

        // GOOD: own data, publish event, circuit-breaker the one sync call.
        log.info("=== decoupled: event + circuit breaker survives slow dependency ===");
        EventBus bus = new EventBus();
        CircuitBreaker breaker = new CircuitBreaker(3);
        DecoupledLoanService decoupled = new DecoupledLoanService(bus, breaker, creditSlow);
        for (int i = 1; i <= 5; i++) decoupled.approve("LN-G" + i, "SAV2001");
    }
}

// ─── bad/CoupledLoanService.java (distributed monolith anti-pattern) ───
class CoupledLoanService {
    private static final Logger log = Logger.getLogger("DM");
    private final DownstreamService account, fraud, credit;
    CoupledLoanService(DownstreamService account, DownstreamService fraud, DownstreamService credit) {
        this.account = account; this.fraud = fraud; this.credit = credit;
    }
    void approve(String loanId, String customerId) {
        try {
            account.callSync();          // loan → account
            fraud.callSync();            // account → fraud
            credit.callSync();           // fraud → credit (SLOW → cascades)
            log.info(() -> "Loan " + loanId + " APPROVED");
        } catch (RuntimeException e) {
            // One slow/failed hop fails the entire request — no isolation.
            log.severe(() -> "Loan " + loanId + " FAILED: chain broke at a downstream hop");
        }
    }
}

// ─── good/DecoupledLoanService.java (own data + event + circuit breaker) ───
class DecoupledLoanService {
    private static final Logger log = Logger.getLogger("DM");
    private final EventBus bus;
    private final CircuitBreaker breaker;
    private final DownstreamService credit;
    DecoupledLoanService(EventBus bus, CircuitBreaker breaker, DownstreamService credit) {
        this.bus = bus; this.breaker = breaker; this.credit = credit;
    }
    void approve(String loanId, String customerId) {
        // Own DB write would happen here (not a shared table).
        // The one truly-synchronous dependency is wrapped in a circuit breaker.
        boolean creditOk = breaker.call(() -> { credit.callSync(); return true; }, true /*fallback*/);
        // Non-critical work is decoupled via an event — no synchronous chain.
        bus.publish("LoanApproved", loanId);
        log.info(() -> "Loan " + loanId + " recorded (creditCheck=" + creditOk
                + ", fraud/account via async events)");
    }
}

// ─── good/EventBus.java (async decoupling — publish and move on) ───
class EventBus {
    private static final Logger log = Logger.getLogger("DM");
    void publish(String type, String key) {
        log.info(() -> "EVENT " + type + " published for " + key + " (consumers react independently)");
    }
}

// ─── good/CircuitBreaker.java (fail fast instead of cascading) ───
class CircuitBreaker {
    private static final Logger log = Logger.getLogger("DM");
    private final int threshold;
    private int failures = 0;
    private boolean open = false;
    CircuitBreaker(int threshold) { this.threshold = threshold; }
    <T> T call(java.util.function.Supplier<T> action, T fallback) {
        if (open) { log.warning("Circuit OPEN — fail fast, return fallback (no cascade)"); return fallback; }
        try {
            T result = action.get();
            failures = 0;
            return result;
        } catch (RuntimeException e) {
            failures++;
            log.warning(() -> "Downstream failed (" + failures + "/" + threshold + ")");
            if (failures >= threshold) { open = true; log.severe("Circuit OPENED"); }
            return fallback;
        }
    }
}

// ─── downstream/DownstreamService.java ───
class DownstreamService {
    private final String name; private final boolean failing;
    DownstreamService(String name, boolean failing) { this.name = name; this.failing = failing; }
    void callSync() {
        if (failing) throw new RuntimeException(name + " slow/failing");
    }
}

// ─── config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
